import React from 'react';

const TABS = [
  { id:'home',      icon:'○', label:'Hem' },
  { id:'checkin',   icon:'◎', label:'Check-in' },
  { id:'history',   icon:'≡', label:'Historik' },
  { id:'breathing', icon:'◯', label:'Andning' },
];

export default function Nav({ page, setPage }) {
  return (
    <div style={{
      position:'fixed', bottom:20, left:'50%', transform:'translateX(-50%)',
      zIndex:100, display:'flex', alignItems:'center', gap:2,
      background:'rgba(30,22,15,0.85)',
      backdropFilter:'blur(24px)',
      border:'1px solid rgba(255,255,255,0.08)',
      borderRadius:100,
      padding:'6px 6px',
      boxShadow:'0 8px 40px rgba(0,0,0,0.5), 0 1px 0 rgba(255,255,255,0.05) inset',
    }}>
      {TABS.map(tab => (
        <button key={tab.id} onClick={() => setPage(tab.id)}
          style={{
            display:'flex', flexDirection:'column', alignItems:'center', gap:2,
            padding:'8px 18px', borderRadius:100, border:'none',
            background: page===tab.id ? 'rgba(255,255,255,0.1)' : 'transparent',
            transition:'all .25s',
          }}>
          <span style={{ fontSize:10, fontFamily:'DM Mono,monospace', letterSpacing:'0.1em', textTransform:'uppercase', color: page===tab.id ? 'rgba(240,235,227,0.9)' : 'rgba(240,235,227,0.28)', transition:'color .25s' }}>
            {tab.label}
          </span>
        </button>
      ))}
    </div>
  );
}
